 async function exportPlan(){await ensureWorker();if(controller.running)throw Error('Pause the run before exporting its accepted task report.');const id=controller.session||lastSession;if(!id)throw Error('Start or load a session first.');const saved=await worker.dispatch({op:'session',session:id}),tasks=[...saved.events].reverse().find(e=>e.kind==='assistant'&&Array.isArray(e.value?.tasks))?.value.tasks;if(!tasks?.length)throw Error('This session has no accepted task list.');const target=await vscode.window.showSaveDialog({defaultUri:vscode.Uri.file(path.join(folder.uri.fsPath,'agent-'+id+'-tasks.md')),filters:{Markdown:['md']}});if(target){await fs.writeFile(target.fsPath,Tasks.markdown(tasks));notify({kind:'info',text:'Accepted task report exported. Statuses and dependencies are plan metadata, not test results.'});}}
