  if(memRoot?.fsPath)await fs.rm(path.join(memRoot.fsPath,'project-memory'),{recursive:true,force:true});
  lastSession=null;sessionStatus='';activeModel=null;modelMetrics=Usage.empty();currentTasks=[];latestVerification=null;providerRecovery=null;lastContextBudget=null;sessionSummary=null;outputView=null;previewedActions.clear();reviewSession=null;attachments=[];trace.length=0;
