 async function resolveFailure(message){
  const text=String(message?.text||'Run failed').slice(0,500);
  const picked=await vscode.window.showQuickPick([
   {label:'Retry / Resume with recovery note',value:'retry'},
   {label:'Open RabbitHole Settings',value:'settings'},
   {label:'Configure Model Provider',value:'provider'},
   {label:'Start New Session',value:'newSession'},
   {label:'Copy Error Details',value:'copy'}
  ],{title:'Resolve Failure',placeHolder:text});
  if(!picked)return;
  if(picked.value==='retry'){pendingDrafts.push({id:crypto.randomBytes(16).toString('hex'),workspaceKey:state().workspaceKey,label:'Failure recovery',text:'Resolve the previous failure and continue:\n'+text});send(state());}
  else if(picked.value==='settings'){await vscode.commands.executeCommand('workbench.action.openSettings','codingagent');}
  else if(picked.value==='provider'){await settings();}
  else if(picked.value==='newSession'){await resetSession();}
  else if(picked.value==='copy'){await vscode.env?.clipboard?.writeText(String(message?.text||text));}
 }
